// HasDiocese applies the HasEdge predicate on the "diocese" edge.
func HasDiocese() predicate.Parish {
	return predicate.Parish(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, DioceseTable, DioceseColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasDioceseWith applies the HasEdge predicate on the "diocese" edge with a given conditions (other predicates).
func HasDioceseWith(preds ...predicate.Diocese) predicate.Parish {
	return predicate.Parish(func(s *sql.Selector) {
		step := newDioceseStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

