// And groups predicates with the AND operator between them.
func And(predicates ...predicate.Parish) predicate.Parish {
	return predicate.Parish(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.Parish) predicate.Parish {
	return predicate.Parish(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.Parish) predicate.Parish {
	return predicate.Parish(sql.NotPredicates(p))
}
